 if home:head+='''<style>#opening{opacity:0;visibility:hidden;pointer-events:none;animation:maison-opening-exit 2.3s both}#opening.is-hidden{animation:none;opacity:0;visibility:hidden;pointer-events:none}#conteudo:target~#opening{display:none}@keyframes maison-opening-exit{0%,72%{opacity:1;visibility:visible;pointer-events:auto}100%{opacity:0;visibility:hidden;pointer-events:none}}@media(prefers-reduced-motion:reduce){#opening{display:none;animation:none}}</style>'''
